import { createApp } from './dist/app.js';

/**
 * Vercel entrypoint for the `server` service: the same API as the Node host, with no
 * app.listen() (a serverless function ends with its response) and no Telegram poll loop
 * (webhook delivery plus the daily cron in vercel.json replace it).
 *
 * `dist/` is generated by this service's build command, `npm run build`.
 */
export default createApp();
